public interface IPaymentService{Task<PaymentInitiation> InitiateAsync(Order order,CancellationToken cancellationToken=default);Task<PaymentVerification> VerifyAsync(string orderNumber,IReadOnlyDictionary<string,string> callback,CancellationToken cancellationToken=default);}
public sealed record PaymentInitiation(string Gateway,string Status,string? RedirectUrl);
public sealed record PaymentVerification(bool Success,string Status,string? TransactionId,string? Error);
public sealed class PaytmPaymentService(IConfiguration configuration):IPaymentService
{
 public Task<PaymentInitiation> InitiateAsync(Order order,CancellationToken cancellationToken=default){var enabled=configuration["Paytm:Enabled"]?.Equals("true",StringComparison.OrdinalIgnoreCase)==true;if(!enabled)return Task.FromResult(new PaymentInitiation("PAYTM","CONFIGURATION_REQUIRED",null));var checkout=configuration["Paytm:CheckoutUrl"];if(string.IsNullOrWhiteSpace(checkout))return Task.FromResult(new PaymentInitiation("PAYTM","GATEWAY_NOT_CONFIGURED",null));return Task.FromResult(new PaymentInitiation("PAYTM","READY",checkout));}
 public Task<PaymentVerification> VerifyAsync(string orderNumber,IReadOnlyDictionary<string,string> callback,CancellationToken cancellationToken=default){var enabled=configuration["Paytm:Enabled"]?.Equals("true",StringComparison.OrdinalIgnoreCase)==true;if(!enabled)return Task.FromResult(new PaymentVerification(false,"UNVERIFIED",null,"Paytm is not configured."));return Task.FromResult(new PaymentVerification(false,"UNVERIFIED",null,"Paytm checksum/signature verification is required before enabling payment settlement."));}
}
